// Generated by OrchestKit Claude Plugin
// Created: 2026-07-29

// Regression suite for the two defects that made ⌘K search read as broken:
//   1. components/search-dialog dropped every heading/text row, so results
//      were bare page titles with no evidence of the match.
//   2. lib/search-relevance scored by list position SCALED by doc-type weight,
//      so a guide mentioning a term once outranked a reference page
//      documenting it eight times.
// Both are pinned here against the real shape of /api/search?query=tavily.

import { describe, expect, it } from "vitest";
import {
	MAX_SNIPPETS_PER_PAGE,
	TOP_RESULTS_LABEL,
	buildDisplayList,
	flattenBlocks,
	toBlocks,
} from "@/lib/search-display";
import { rerankByRelevance } from "@/lib/search-relevance";

type Row = {
	id: string;
	url: string;
	type: "page" | "heading" | "text";
	content: string;
};

/** Build a page row plus `n` matched text rows, as the search API emits them. */
function block(url: string, title: string, n: number): Row[] {
	const rows: Row[] = [{ id: url, url, type: "page", content: title }];
	for (let i = 0; i < n; i++) {
		rows.push({
			id: `${url}-${i}`,
			url: `${url}#s${i}`,
			type: "text",
			content: `<mark>tavily</mark> ${i}`,
		});
	}
	return rows;
}

describe("toBlocks", () => {
	it("groups each page with the rows matched inside it", () => {
		const blocks = toBlocks([...block("/a", "A", 2), ...block("/b", "B", 1)]);

		expect(blocks).toHaveLength(2);
		expect(blocks[0].page.url).toBe("/a");
		expect(blocks[0].children).toHaveLength(2);
		expect(blocks[1].children).toHaveLength(1);
	});

	it("keeps a leading orphan row instead of dropping it", () => {
		const blocks = toBlocks([
			{ id: "x", url: "/x#h", type: "text", content: "orphan" },
			...block("/a", "A", 1),
		]);

		expect(blocks).toHaveLength(2);
		expect(blocks[0].page.id).toBe("x");
	});
});

describe("flattenBlocks (response bounding)", () => {
	// Without a cap the API returns every matched row. A one-character query
	// like "m" is 2180 rows / 433 KB, re-fetched on every keystroke. The dialog
	// renders at most 2 snippets per page, so it asks for 2 (85x smaller).
	const blocks = toBlocks([...block("/a", "A", 8), ...block("/b", "B", 5)]);

	it("keeps every sub-row when uncapped, preserving the old contract", () => {
		expect(flattenBlocks(blocks, null)).toHaveLength(15);
	});

	it("caps sub-rows per page without dropping any page", () => {
		const rows = flattenBlocks(blocks, 2);

		expect(rows.filter((r) => r.type === "page")).toHaveLength(2);
		expect(rows).toHaveLength(6);
	});

	it("keeps the page row even at maxSnippets=0", () => {
		const rows = flattenBlocks(blocks, 0);

		expect(rows).toHaveLength(2);
		expect(rows.every((r) => r.type === "page")).toBe(true);
	});

	it("leaves a page with fewer snippets than the cap untouched", () => {
		const rows = flattenBlocks(toBlocks(block("/a", "A", 1)), 5);

		expect(rows).toHaveLength(2);
	});
});

describe("buildDisplayList", () => {
	it("keeps matched snippets so the match is visible (defect 1)", () => {
		const { items } = buildDisplayList(block("/docs/guides/x", "X", 3));

		expect(items.filter((i) => i.type !== "page").length).toBeGreaterThan(0);
	});

	it("caps snippets per page so one dense page cannot crowd the list", () => {
		const { items } = buildDisplayList(block("/docs/guides/x", "X", 8));

		expect(items.filter((i) => i.type === "text")).toHaveLength(
			MAX_SNIPPETS_PER_PAGE,
		);
	});

	it("keeps each page contiguous with its own snippets", () => {
		const { items } = buildDisplayList([
			...block("/docs/guides/a", "A", 2),
			...block("/docs/guides/b", "B", 2),
		]);
		const urls = items.map((i) => i.url);

		// Every row between page A and page B belongs to A.
		const bIndex = urls.indexOf("/docs/guides/b");
		expect(urls.slice(0, bIndex).every((u) => u.startsWith("/docs/guides/a"))).toBe(
			true,
		);
	});

	it("anchors section headers on page rows, never on a snippet", () => {
		const { items, headerById } = buildDisplayList(
			block("/docs/guides/x", "X", 3),
		);
		const headed = items.filter((i) => headerById[i.id] !== undefined);

		expect(headerById[items[0].id]).toBe(TOP_RESULTS_LABEL);
		expect(headed.every((i) => i.type === "page")).toBe(true);
	});
});

describe("rerankByRelevance match-count signal (defect 2)", () => {
	// The real /api/search?query=tavily blocks, with their snippet counts.
	// Before the fix this exact input ranked configuration (3) and faq (3)
	// above mcp-servers (8) and reference/skills/configure (8).
	const TAVILY = [
		{ url: "/docs/getting-started/configuration", title: "Configuration", matchCount: 3 },
		{ url: "/docs/troubleshooting/faq", title: "FAQ", matchCount: 3 },
		{ url: "/docs/getting-started/installation", title: "Installation", matchCount: 6 },
		{ url: "/docs/foundations/mcp-servers", title: "MCP Servers", matchCount: 8 },
		{ url: "/docs/reference/skills/configure", title: "Configure", matchCount: 8 },
		{ url: "/docs/reference/skills/mcp-patterns", title: "Mcp Patterns", matchCount: 5 },
	];

	it("ranks the pages that document the term above passing mentions", () => {
		const ranked = rerankByRelevance(TAVILY, "tavily").map((b) => b.url);

		expect(ranked.slice(0, 2)).toEqual([
			"/docs/foundations/mcp-servers",
			"/docs/reference/skills/configure",
		]);
		// The two 3-snippet pages must no longer lead.
		expect(ranked.indexOf("/docs/getting-started/configuration")).toBeGreaterThan(2);
	});

	it("lets doc-type break a tie but never override match count", () => {
		const ranked = rerankByRelevance(
			[
				{ url: "/docs/reference/skills/a", title: "A", matchCount: 8 },
				{ url: "/docs/guides/b", title: "B", matchCount: 3 },
			],
			"q",
		).map((b) => b.url);

		// Guide weight (1.35) must not rescue a 3-snippet page over an 8.
		expect(ranked[0]).toBe("/docs/reference/skills/a");
	});

	it("uses doc-type as the tiebreak at equal match count", () => {
		const ranked = rerankByRelevance(
			[
				{ url: "/docs/reference/skills/a", title: "A", matchCount: 4 },
				{ url: "/docs/guides/b", title: "B", matchCount: 4 },
			],
			"q",
		).map((b) => b.url);

		expect(ranked[0]).toBe("/docs/guides/b");
	});

	it("keeps the exact-title floor above the match-count signal", () => {
		const ranked = rerankByRelevance(
			[
				{ url: "/docs/foundations/x", title: "Other", matchCount: 40 },
				{ url: "/docs/reference/skills/commit", title: "commit", matchCount: 1 },
			],
			"commit",
		).map((b) => b.url);

		expect(ranked[0]).toBe("/docs/reference/skills/commit");
	});

	it("degrades to position + type when matchCount is absent", () => {
		const ranked = rerankByRelevance(
			[
				{ url: "/docs/reference/skills/a", title: "A" },
				{ url: "/docs/guides/b", title: "B" },
			],
			"q",
		).map((b) => b.url);

		expect(ranked).toHaveLength(2);
		expect(ranked[0]).toBe("/docs/guides/b");
	});
});
